{"source":"#!/usr/bin/env python3
import csv
import json
import sys


def main():
    filename = sys.argv[1]
    totals = {}
    with open(filename, encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            raw = row.get("item", "")
            name = " ".join(raw.split()).lower()
            if not name:
                continue
            qty_raw = row.get("quantity", "").strip()
            if qty_raw == "":
                qty = 1
            else:
                qty = int(qty_raw, 10)
            totals[name] = totals.get(name, 0) + qty

    result = [{"item": name, "quantity": qty} for name, qty in sorted(totals.items())]
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
"}

